import 'package:flutter_test/flutter_test.dart';
import 'package:itqan/features/gamification/domain/models/gamification_models.dart';

void main(){test('profile level parses max-level contract',(){final p=GamificationProfile.fromJson({'user':{'id':2,'name':'A'},'stats':{'total_xp':100,'total_coins':4,'level':{'number':8,'title':'متقدم','current_threshold':90,'next_threshold':90,'progress_percentage':100,'xp_to_next_level':0,'is_max_level':true}}});expect(p.totalXp,100);expect(p.level?.isMaxLevel,true);});test('leaderboard preserves null rank and valid ranks',(){final l=Leaderboard.fromJson({'period':'all_time','score_type':'xp','top':[{'rank':1,'user_id':3,'name':'User','level':2,'level_title':'متعلم','score':40}],'me':{'rank':null,'user_id':9,'name':'Me','level':1,'level_title':'مبتدئ','score':0,'in_top':false}});expect(l.top.single.rank,1);expect(l.me.rank,isNull);});test('activity parses duplicate response without local reward assumptions',(){final a=ActivityResult.fromJson({'success':true,'duplicate':true,'data':{'activity_id':5,'verification_status':'approved','xp_earned':0,'coins_earned':0,'xp_balance':14,'coin_balance':2,'task_progress':[],'task_rewards':[],'new_achievements':[]}});expect(a.duplicate,true);expect(a.xpEarned,0);expect(a.xpBalance,14);});}
